div.egXML:
&lt;xsl:template match="TEI"&gt;
    &lt;html&gt;
        &lt;head&gt;&lt;title&gt;Le dernier jour d’un condamné&lt;/title&gt;&lt;/head&gt;
        &lt;body&gt;
            &lt;ul&gt;
                &lt;xsl:apply-templates
                    select="//div/head" mode="toc"/&gt;
            &lt;/ul&gt;
            &lt;xsl:apply-templates/&gt;
        &lt;/body&gt;
    &lt;/html&gt;
&lt;/xsl:template&gt;

&lt;xsl:variable name="msg" select="'Hello World!'"&gt;
&lt;xsl:template match="div"&gt;
    &lt;xsl:variable name="id" select="@xml:id"/&gt;
    &lt;section id="{ $id }"&gt;
        &lt;xsl:apply-template/&gt;
    &lt;/section&gt;
&lt;/xsl:template&gt;
&lt;xsl:template match="p"&gt;
&lt;!-- impossible ici d'appeler $id, mais on peut appeler $msg--&gt;
&lt;xsl:value-of select="$msg"&gt;
&lt;xsl:template&gt;

&lt;xsl:if test="expression_booléenne"&gt;
   &lt;!-- Mon modèle a appliquer si la condition est vraie --&gt;
&lt;/xsl:if&gt;
